/* Focus, single-file vanilla JS. All saved data lives in this user's browser or in their Supabase row. */
'use strict';
const STORAGE='focus_app_state_v1', SESSION_STORAGE='focus_app_session_v1', META_STORAGE='focus_app_meta_v1';
const CFG=window.FOCUS_CONFIG||{};
const CLOUD_URL=String(CFG.supabaseUrl||'').replace(/\/+$/,'');
const CLOUD_KEY=String(CFG.supabasePublishableKey||'');
const cloudConfigured=/^https:\/\/[^/]+\.supabase\.co$/.test(CLOUD_URL) && !!CLOUD_KEY;
const $=(s,root=document)=>root.querySelector(s);
const safe=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>typeof crypto!=='undefined'&&crypto.randomUUID?crypto.randomUUID():'id'+Date.now().toString(36)+Math.random().toString(36).slice(2);
const read=(k,fallback)=>{try{const x=localStorage.getItem(k);return x?JSON.parse(x):fallback;}catch{return fallback;}};
const saveTo=(k,v)=>localStorage.setItem(k,JSON.stringify(v));
const today=()=>{const parts=new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Kuala_Lumpur',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const get=t=>parts.find(p=>p.type===t).value;return `${get('year')}-${get('month')}-${get('day')}`;};
const month=()=>today().slice(0,7);
const shift=(date,delta)=>{const d=new Date(`${date}T12:00:00Z`);d.setUTCDate(d.getUTCDate()+delta);return d.toISOString().slice(0,10);};
const monStart=d=>{const day=new Date(d+'T12:00:00Z').getUTCDay();return shift(d,-((day+6)%7));};
const datesThisWeek=()=>Array.from({length:7},(_,i)=>shift(monStart(today()),i));
const monthName=(m=month())=>m.replace('-', '年')+'月';
const dateName=d=>{const dt=new Date(d+'T12:00:00Z');return `${dt.getUTCMonth()+1}月${dt.getUTCDate()}日`;};
const money=n=>'RM '+Number(n||0).toLocaleString('en-MY',{minimumFractionDigits:2,maximumFractionDigits:2});
const asNumber=v=>Math.max(0,Number(v)||0);
const isValidDate=x=>/^\d{4}-\d{2}-\d{2}$/.test(x)&&!Number.isNaN(Date.parse(x+'T12:00:00Z'));
function seed(){const m=month();return {version:1,profile:{focus:'建立稳定现金流，并完成一项专业作品',skill:'医疗会议数字化运营与自动化',weeklyTarget:3},habits:[
{id:'quiet',name:'15分钟不刷手机',hint:'给大脑一点安静时间',category:'生活'},
{id:'walk',name:'散步20至30分钟',hint:'身体不适时降低强度',category:'健康'},
{id:'english',name:'英文10分钟',hint:'优先学工作上用得到的表达',category:'学习'},
{id:'expense',name:'记录今天的支出',hint:'先记录，再慢慢优化财务',category:'财务'},
{id:'review',name:'3分钟复盘今天',hint:'写下明天最重要的一件事',category:'生活'},
{id:'reading',name:'阅读 / 听书30分钟',hint:'可分段累计，读完记录收获',category:'学习'}],checks:{},busyDays:{},studyEntries:{},monthlyFocus:{[m]:'确认真实财务状况，建立每周记账习惯'},monthlyTasks:{[m]:[
{id:uid(),title:'核对银行、信用卡和分期余额',done:false},
{id:uid(),title:'写出每月固定支出和最低还款额',done:false},
{id:uid(),title:'连续4周完成每周财务检查',done:false}]},transactions:[],readingEntries:[],accounts:ACCOUNT_TEMPLATES.map(([id,name,type])=>({id,name,type,openingBalance:null,startDate:today(),minimumPayment:null,dueDay:null,notes:''})),reviews:{}};}
const ACCOUNT_TEMPLATES=[
  ['maybank','Maybank','bank'],['tng','Touch ‘n Go eWallet','wallet'],['cash','现金 Cash','cash'],['grab','Grab Wallet','wallet'],
  ['mastergold','MasterGold','credit'],['amex','AMEX','credit'],['spaylater','SPayLater','installment'],['grabpaylater','Grab PayLater','installment']
];

const initial=seed();
let state=read(STORAGE,null)||initial;
function normalize(s){if(!s||typeof s!=='object'||!Array.isArray(s.habits)||!Array.isArray(s.transactions))return normalize(seed());const def=seed();const habits=[...s.habits];if(!habits.some(h=>h.id==='reading'))habits.push(def.habits.find(h=>h.id==='reading'));const templates=ACCOUNT_TEMPLATES.map(([id,name,type])=>({id,name,type,openingBalance:null,startDate:today(),minimumPayment:null,dueDay:null,notes:''}));const existing=Array.isArray(s.accounts)?s.accounts:[];const accs=[...existing];for(const x of templates){if(!accs.some(a=>a.id===x.id))accs.push(x);}return {...def,...s,version:2,habits,accounts:accs,readingEntries:Array.isArray(s.readingEntries)?s.readingEntries:[],profile:{...def.profile,...s.profile},checks:s.checks||{},busyDays:s.busyDays||{},studyEntries:s.studyEntries||{},monthlyTasks:s.monthlyTasks||{},monthlyFocus:s.monthlyFocus||{},reviews:s.reviews||{}};}
state=normalize(state);
let session=read(SESSION_STORAGE,null),meta=read(META_STORAGE,null),page='today',dirty=false,syncIssue='',syncTimer=null,syncing=false,toastTimer=null;
function notice(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3200);}
function commit(msg){saveTo(STORAGE,state);if(session){setDirty(true);scheduleSync();}render();if(msg)notice(msg);}
function updateStatus(){const el=$('#sync-status');if(!el)return;el.className='status-pill';if(!cloudConfigured){el.textContent='● 本机保存';return;}if(!session){el.textContent='● 尚未登录';return;}if(syncIssue){el.textContent='● 同步需处理';el.classList.add('error');return;}if(syncing||dirty){el.textContent='◌ 同步中';return;}el.textContent='● 云端已同步';el.classList.add('connected');}
function route(p){page=p;render();window.scrollTo({top:0,behavior:'instant'});}
function showPageTitle(){const titles={today:'人生工作台',plan:'目标计划',reading:'阅读与听书',money:'财务管理',review:'月度回顾',settings:'设置与同步'};$('#header-title').textContent=titles[page];if($('#header-date'))$('#header-date').textContent=new Date(today()+'T12:00:00Z').toLocaleDateString('zh-CN',{timeZone:'UTC',year:'numeric',month:'long',day:'numeric',weekday:'long'});document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));updateStatus();}
function pageHeading(label,title,subtitle,right=''){return `<div class="page-heading"><div><div class="eyebrow">${safe(label)}</div><h1>${safe(title)}</h1><p class="lead">${safe(subtitle)}</p></div>${right?`<div class="heading-right">${right}</div>`:''}</div>`;}
function banner(){if(syncIssue==='conflict')return `<div class="banner warn"><span><strong>发现不同设备的更新。</strong> 请到「设置与同步」选择保留哪一份数据，系统不会自动覆盖。</span><button data-page="settings" class="btn btn-small">处理冲突</button></div>`;if(syncIssue)return `<div class="banner warn"><span>云端同步暂时失败，本机记录已保留。连网后可重试。</span><button data-action="retry-sync" class="btn btn-small">重试同步</button></div>`;return '';}
function isBusy(){return !!state.busyDays[today()];}
function habitsForToday(){return isBusy()?state.habits.filter(h=>['quiet','reading','expense','review'].includes(h.id)):state.habits;}
function doneHabits(){return habitsForToday().filter(h=>isHabitDone(h)).length;}
function thisMonthExpenses(){return state.transactions.filter(t=>t.date.startsWith(month())&&t.type==='expense').reduce((s,t)=>s+asNumber(t.amount),0);}
function thisMonthIncome(){return state.transactions.filter(t=>t.date.startsWith(month())&&t.type==='income').reduce((s,t)=>s+asNumber(t.amount),0);}
function studyDatesThisWeek(){return datesThisWeek().filter(d=>asNumber(state.studyEntries[d])>=15).length;}
function studyThisMonth(){return Object.entries(state.studyEntries).filter(([d])=>d.startsWith(month())).reduce((s,[,n])=>s+asNumber(n),0);}
function dailyHabitsHTML(){const hs=habitsForToday(),completed=doneHabits(),pct=hs.length?Math.round(completed/hs.length*100):0;return `<div class="ring-wrap"><div class="ring" style="background:conic-gradient(#36b795 ${pct}%,#e9eef3 0)"><div class="ring-label">${pct}%<small>今日进度</small></div></div><div class="ring-copy"><strong>${completed===hs.length?'今天做到了！':'完成一点，就是进步。'}</strong><p>已完成 ${completed} / ${hs.length} 项。<br>不要求完美，持续更重要。</p></div></div><div class="habit-list">${hs.map(h=>{const checked=isHabitDone(h);const displayName=isBusy()&&h.id==='quiet'?'5分钟不刷手机':isBusy()&&h.id==='review'?'1分钟复盘':h.name;const c=h.category==='健康'?'health':h.category==='财务'?'money':h.category==='学习'?'study':'';return `<div class="habit-row ${checked?'done':''}"><button class="checkmark" data-action="toggle-habit" data-id="${safe(h.id)}" aria-label="${safe(checked?'取消':'完成')}${safe(displayName)}">${checked?'✓':''}</button><div class="habit-detail"><div class="habit-title">${safe(displayName)}</div><div class="habit-hint">${safe(h.hint)}</div></div><span class="tag ${c}">${safe(h.category)}</span></div>`;}).join('')}</div>`;}
function weeklyDots(){return `<div class="week-dots">${datesThisWeek().map((d,i)=>`<div class="week-day"><span>${'一二三四五六日'[i]}</span><div title="${d}: ${asNumber(state.studyEntries[d])}分钟" class="week-dot ${asNumber(state.studyEntries[d])>=15?'filled':''} ${d===today()?'today':''}">${asNumber(state.studyEntries[d])>=15?'✓':asNumber(state.studyEntries[d])||'·'}</div></div>`).join('')}</div>`;}
function monthlyItems(){return state.monthlyTasks[month()]||[];}
function tasksHTML(limit=false){const items=monthlyItems(),arr=limit?items.slice(0,4):items;if(!arr.length)return '<div class="empty">这个月还没有任务。<br>添加一个简单、可完成的目标。</div>';return `<div class="list-clean">${arr.map(t=>`<div class="task-row ${t.done?'checked':''}"><button class="task-check" data-action="toggle-task" data-id="${safe(t.id)}" aria-label="切换任务完成">${t.done?'✓':''}</button><span class="task-text">${safe(t.title)}</span>${!limit?`<button class="mini-delete" data-action="delete-task" data-id="${safe(t.id)}" aria-label="删除任务">×</button>`:''}</div>`).join('')}</div>`;}
function todaysTransactions(){return [...state.transactions].filter(t=>t.date===today()).slice(-4).reverse();}
function recentTransactionsHTML(list){if(!list.length)return '<div class="empty">还没有记录。<br>从第一笔支出开始就好。</div>';return list.map(t=>`<div class="transaction"><div class="left"><div class="transaction-icon">${t.type==='income'?'＋':'◉'}</div><div style="min-width:0"><div class="transaction-name">${safe(t.note||t.category)}</div><div class="transaction-info">${safe(dateName(t.date))} · ${safe(t.category)} · ${t.type==='income'?'收入':'支出'}</div></div></div><div class="tx-actions"><div class="transaction-amount ${t.type}">${t.type==='income'?'+':'−'}${money(t.amount)}</div><button class="mini-delete" data-action="delete-tx" data-id="${safe(t.id)}" aria-label="删除记录">×</button></div></div>`).join('');}
// v2: reading minutes and double-entry-style balance changes for user-maintained accounts.
const accountKind=type=>['credit','installment','loan'].includes(type)?'debt':'asset';
const accountTypeText={bank:'银行账户',wallet:'电子钱包',cash:'现金',credit:'信用卡',installment:'分期欠款',loan:'贷款'};
const accountIcon={bank:'▣',wallet:'◈',cash:'◉',credit:'▤',installment:'▦',loan:'⌂'};
const allAccounts=()=>state.accounts||[];
const accountById=id=>allAccounts().find(a=>a.id===id);
const knownAccounts=()=>allAccounts().filter(a=>a.openingBalance!==null&&Number.isFinite(Number(a.openingBalance)));
const hasBalance=a=>a.openingBalance!==null&&a.openingBalance!==''&&Number.isFinite(Number(a.openingBalance));
const signed=n=>`${n<0?'−':''}${money(Math.abs(n))}`;
function balanceOf(account){if(!account||!hasBalance(account))return null;let value=Number(account.openingBalance);for(const tx of state.transactions){if(!tx.date||tx.date<(account.startDate||'0000-01-01'))continue;const v=Number(tx.amount)||0;
if(tx.type==='income'&&tx.accountId===account.id)value+=v;
if(tx.type==='expense'&&tx.accountId===account.id)value+=accountKind(account.type)==='debt'?v:-v;
if(tx.type==='transfer'){
if(tx.fromAccountId===account.id)value-=v;
if(tx.toAccountId===account.id)value+=accountKind(account.type)==='debt'?-v:v;
}
if(tx.type==='adjustment'&&tx.accountId===account.id)value+=Number(tx.delta)||0;
}return Math.round(value*100)/100;}
const assetTotal=()=>knownAccounts().filter(a=>accountKind(a.type)==='asset').reduce((s,a)=>s+(balanceOf(a)||0),0);
const debtTotal=()=>knownAccounts().filter(a=>accountKind(a.type)==='debt').reduce((s,a)=>s+(balanceOf(a)||0),0);
const missingAccounts=()=>allAccounts().filter(a=>!hasBalance(a));
const accountLabel=id=>accountById(id)?.name||'未指定账户（旧记录）';
const chosenAccount=(id)=>accountById(id)||null;
function accountOptions(type='all',selected='',placeholder='请选择账户'){
const a=allAccounts().filter(x=>type==='all'||(type==='asset'?accountKind(x.type)==='asset':accountKind(x.type)==='debt'));
return `<option value="">${safe(placeholder)}</option>${a.map(x=>`<option value="${safe(x.id)}" ${selected===x.id?'selected':''}>${safe(x.name)}${!hasBalance(x)?'（待核对余额）':''}</option>`).join('')}`;
}
function txAccountNames(t){if(t.type==='transfer')return `${accountLabel(t.fromAccountId)} → ${accountLabel(t.toAccountId)}`;if(t.type==='adjustment')return accountLabel(t.accountId);return t.accountId?accountLabel(t.accountId):'旧版未关联账户';}
function transactionLabel(t){if(t.type==='transfer')return accountKind(chosenAccount(t.toAccountId)?.type)==='debt'?'转账还款':'账户转账';if(t.type==='adjustment')return '余额对账';return t.type==='income'?'收入':'支出';}
function financeTransactionsHTML(list){if(!list.length)return '<div class="empty">还没有交易。先设定账户余额，再记录第一笔。</div>';return list.map(t=>`<div class="transaction finance-tx"><div class="left"><div class="transaction-icon ${t.type}">${t.type==='income'?'↗':t.type==='expense'?'↘':t.type==='transfer'?'⇄':'≈'}</div><div style="min-width:0"><div class="transaction-name">${safe(t.note||transactionLabel(t))}</div><div class="transaction-info">${safe(t.date)} · ${safe(transactionLabel(t))} · ${safe(txAccountNames(t))}${t.category?' · '+safe(t.category):''}</div></div></div><div class="tx-actions"><div class="transaction-amount ${safe(t.type)}">${t.type==='income'?'+':t.type==='expense'?'−':t.type==='transfer'?'⇄':''}${t.type==='adjustment'?signed(t.delta):money(t.amount)}</div><button class="edit-tx" data-action="edit-tx" data-id="${safe(t.id)}">编辑</button><button class="mini-delete" data-action="delete-tx" data-id="${safe(t.id)}" aria-label="删除交易">×</button></div></div>`).join('');}
const readingEntriesToday=()=>state.readingEntries.filter(e=>e.date===today());
const readingMinutesFor=date=>state.readingEntries.filter(e=>e.date===date).reduce((s,e)=>s+(Number(e.minutes)||0),0);
const readingMinutesMonth=()=>state.readingEntries.filter(e=>e.date.startsWith(month())).reduce((s,e)=>s+(Number(e.minutes)||0),0);
const readingDaysMonth=()=>Object.keys(state.readingEntries.reduce((acc,e)=>{if(e.date.startsWith(month()))acc[e.date]=true;return acc;},{})).filter(d=>readingMinutesFor(d)>=30).length;
function isHabitDone(h,date=today()){return h.id==='reading'?readingMinutesFor(date)>=30:!!state.checks[date]?.[h.id];}
function habitSmallIcon(id){return ({quiet:'☼',walk:'↗',english:'A',reading:'▤',expense:'◈',review:'✎'})[id]||'✓';}
function readingProgress(){const n=readingMinutesFor(today());const pct=Math.min(100,Math.round(n/30*100));return `<div class="reading-progress"><div class="reading-progress-top"><div><span class="micro-label">今日阅读 / 听书</span><div class="reading-time">${n}<small> / 30 分钟</small></div></div><div class="reading-book-icon">▤</div></div><div class="progress-rail"><div class="progress-fill" style="width:${pct}%"></div></div><div class="reading-progress-bottom"><span>${n>=30?'今天的阅读目标已达成':'看书和听书可以累计时间'}</span><button class="link-btn" data-page="reading">记录时间 ›</button></div></div>`;}
function monthCalendar(){const m=month(),y=Number(m.slice(0,4)),mo=Number(m.slice(5,7));const first=new Date(Date.UTC(y,mo-1,1)).getUTCDay();const offset=(first+6)%7;const n=new Date(Date.UTC(y,mo,0)).getUTCDate();const cells=Array.from({length:offset},()=>null).concat(Array.from({length:n},(_,i)=>i+1));return `<div class="mini-calendar"><div class="calendar-head"><strong>${monthName()}</strong><span>有打卡的日子会亮起</span></div><div class="calendar-grid">${'一二三四五六日'.split('').map(w=>`<span class="weekday">${w}</span>`).join('')}${cells.map(day=>{if(!day)return '<span class="cal-empty"></span>';const d=m+'-'+String(day).padStart(2,'0');const completed=state.habits.some(h=>isHabitDone(h,d));return `<span title="${d}" class="cal-day ${d===today()?'current':''} ${completed?'active':''}">${day}</span>`;}).join('')}</div></div>`;}
function updatedHabitsHTML(){return `<div class="habit-tile-grid">${habitsForToday().map(h=>{const done=isHabitDone(h);return `<button class="habit-tile ${done?'is-done':''} ${h.id==='reading'?'habit-reading':''}" data-action="${h.id==='reading'?'go-reading':'toggle-habit'}" data-id="${safe(h.id)}"><span class="habit-tile-icon">${habitSmallIcon(h.id)}</span><span class="habit-tile-name">${safe(h.name)}</span><span class="habit-tile-foot">${h.id==='reading'?readingMinutesFor(today())+'/30 分钟':done?'今天已完成':'点击打卡'}</span><span class="habit-tile-check">${done?'✓':'○'}</span></button>`;}).join('')}</div>`;}
function heroArtwork(){return `<div class="hero-art" aria-hidden="true"><svg viewBox="0 0 490 220" xmlns="http://www.w3.org/2000/svg"><defs><linearGradient id="desk" x1="0" x2="0" y1="0" y2="1"><stop stop-color="#e8c5a7"/><stop offset="1" stop-color="#d9aa84"/></linearGradient><linearGradient id="cup" x1="0" x2="1"><stop stop-color="#c77953"/><stop offset="1" stop-color="#e7a77d"/></linearGradient></defs><ellipse cx="256" cy="206" rx="227" ry="12" fill="#dac4af" opacity=".34"/><path d="M13 194h464v8H13z" fill="url(#desk)"/><g opacity=".95"><path d="M326 179h109v15H326z" fill="#bba085" rx="4"/><rect x="312" y="162" width="132" height="17" rx="4" fill="#44677a"/><rect x="335" y="143" width="110" height="18" rx="3" fill="#dfc9ad"/><path d="M363 147h75" stroke="#b49e8a" stroke-width="1"/><rect x="302" y="184" width="145" height="9" rx="3" fill="#6e7878"/></g><g><path d="M267 88h117c-8-47-107-48-117 0" fill="#d4b18c"/><path d="M326 89v61" stroke="#987f62" stroke-width="5" stroke-linecap="round"/><path d="M301 152h51" stroke="#987f62" stroke-width="6" stroke-linecap="round"/><ellipse cx="326" cy="148" rx="34" ry="5" fill="#bba083" opacity=".3"/></g><g><path d="M145 151h73l-6 42h-61z" fill="url(#cup)"/><path d="M214 161h15a16 16 0 0 1 0 30h-14" stroke="#bf6a46" stroke-width="8" fill="none"/><ellipse cx="181" cy="151" rx="37" ry="7" fill="#e5a17a"/></g><g><path d="M453 75c-4-31 9-51 22-63" stroke="#70884f" stroke-width="3" fill="none"/><path d="M458 77c-38-5-45-26-42-40 26-5 40 18 42 40" fill="#8daa64"/><path d="M468 60c25-15 35-31 26-46-23 5-30 23-26 46" fill="#759754"/><path d="M460 120c-23-21-37-15-43 0 14 17 30 16 43 0" fill="#9ab56a"/><path d="M449 171c-35-15-44-4-45 12 19 13 37 6 45-12" fill="#7d9e58"/><path d="M461 125c-6-16-10-35-8-52" stroke="#6b8453" stroke-width="3" fill="none"/><path d="M444 129h47l-9 65h-30z" fill="#eee6d6"/><path d="M438 129h59" stroke="#d6cabc" stroke-width="5"/></g><g fill="#e1bca5" opacity=".54"><circle cx="252" cy="56" r="3"/><circle cx="257" cy="35" r="2"/><circle cx="122" cy="49" r="4"/></g></svg></div>`;}
function updatedTodayPage(){const hs=habitsForToday(),hDone=hs.filter(h=>isHabitDone(h)).length,mt=monthlyItems(),pct=hs.length?Math.round(hDone/hs.length*100):0;
const completedWeek=datesThisWeek().filter(d=>state.habits.some(h=>isHabitDone(h,d))).length;
return `<div class="hero-banner"><div class="hero-copy"><span class="hero-kicker">YOUR LITTLE SPACE TO GROW ✳</span><h1>我的人生工作台<span class="hero-underline"></span></h1><p>让目标有方向，让每天有进度。</p><div class="hero-note">今天也为自己前进一点点。</div></div>${heroArtwork()}</div>${banner()}
<div class="stats-grid lively-stats">
<div class="stat-card coral"><div class="stat-label">今日习惯<span class="stat-icon">☑</span></div><div class="stat-number">${hDone}<em> / ${hs.length}</em></div><div class="stat-sub">已经做到了 ${pct}%</div></div>
<div class="stat-card sage"><div class="stat-label">阅读 / 听书<span class="stat-icon">▤</span></div><div class="stat-number">${readingMinutesFor(today())}<em> / 30 分钟</em></div><div class="stat-sub">让知识慢慢积累</div></div>
<div class="stat-card sky"><div class="stat-label">本周学习<span class="stat-icon">◷</span></div><div class="stat-number">${studyDatesThisWeek()}<em> / ${state.profile.weeklyTarget} 次</em></div><div class="stat-sub">短时间，也有收获</div></div>
<div class="stat-card peach"><div class="stat-label">本月任务<span class="stat-icon">↗</span></div><div class="stat-number">${mt.filter(x=>x.done).length}<em> / ${mt.length}</em></div><div class="stat-sub">重要的事慢慢完成</div></div></div>
<div class="dashboard-grid">
<section class="card dashboard-habits"><div class="card-head"><div><div class="card-title">✳ 今天照顾好自己了吗？</div><div class="card-subtitle">每完成一个小习惯，都是值得记录的进步</div></div><button class="btn btn-small ${isBusy()?'btn-mint':''}" data-action="toggle-busy">${isBusy()?'✓ 活动日模式':'活动日模式'}</button></div>${updatedHabitsHTML()}${readingProgress()}</section>
<section class="card dashboard-tasks"><div class="card-head"><div><div class="card-title">☑ 这周最重要的事</div><div class="card-subtitle">不需要一次做完，先做好一件</div></div><button class="link-btn" data-page="plan">全部 ›</button></div>${tasksHTML(true)}<div class="section-divider"></div><div class="small-focus"><span class="micro-label">这个月的主目标</span><p>${safe(state.monthlyFocus[month()]||state.profile.focus)}</p></div></section>
<section class="card dashboard-goal"><div class="card-head"><div><div class="card-title">◎ 今日进度</div><div class="card-subtitle">比昨天前进一步就好</div></div></div><div class="dashboard-ring" style="background:conic-gradient(#80a875 ${pct}%, #e8eadb 0)"><div>${pct}%<small>习惯完成率</small></div></div><div class="goal-legend"><span>✓ 已完成 ${hDone} 项</span><span>○ 还可以做 ${hs.length-hDone} 项</span></div><button class="btn btn-light" data-page="review">记录今天的感受 ›</button></section>
</div>
<div class="dashboard-under-grid"><section class="card dashboard-career"><div class="tile-icon">▧</div><div><h3>职业成长</h3><p>${safe(state.profile.skill)}</p></div><div class="tile-bottom"><span>本周 ${studyDatesThisWeek()} / ${state.profile.weeklyTarget} 次</span><button class="mini-link" data-action="study-25">＋ 25分钟</button></div><div class="progress-rail"><div class="progress-fill" style="width:${Math.min(100,studyDatesThisWeek()/Math.max(1,state.profile.weeklyTarget)*100)}%"></div></div></section>
<section class="card dashboard-health"><div class="tile-icon">♡</div><div><h3>健康与习惯</h3><p>散步、睡眠、稳稳照顾自己</p></div><div class="tile-bottom"><span>本周 ${completedWeek} / 7 天有打卡</span><span>继续加油</span></div><div class="progress-rail"><div class="progress-fill" style="width:${Math.round(completedWeek/7*100)}%"></div></div></section>
<section class="card dashboard-finance"><div class="tile-icon">◈</div><div><h3>财务与储蓄</h3><p>每个账户都清楚，才有选择的底气</p></div><div class="tile-bottom"><span>${knownAccounts().length}/${allAccounts().length} 个账户已核对</span><button class="mini-link" data-page="money">打开财务 ›</button></div><div class="progress-rail"><div class="progress-fill" style="width:${allAccounts().length?Math.round(knownAccounts().length/allAccounts().length*100):0}%"></div></div></section></div>
<div class="dashboard-bottom-grid"><section class="card"><div class="card-head"><div><div class="card-title">◉ 习惯日历</div><div class="card-subtitle">不追求每天满分，只记录持续</div></div></div>${monthCalendar()}</section><section class="card"><div class="card-head"><div><div class="card-title">▤ 阅读角落</div><div class="card-subtitle">阅读或听书，累计30分钟</div></div><button class="link-btn" data-page="reading">记录 ›</button></div><div class="reading-corner-graphic">▤<span>每一页，都算数。</span></div><p class="text-sm muted">这个月已经阅读 / 听书 ${readingMinutesMonth()} 分钟，达标 ${readingDaysMonth()} 天。</p><button class="btn btn-primary" data-page="reading">＋ 记录阅读时间</button></section><section class="card"><div class="card-head"><div><div class="card-title">✎ 今天的小回顾</div><div class="card-subtitle">花3分钟看看自己走了多远</div></div></div><p class="reflection-quote">“不要因为今天还没做到全部，就忽略自己已经完成的部分。”</p><button class="btn btn-light" data-page="review">打开月度回顾 ›</button><button class="btn btn-light" data-page="money">查看完整财务 ›</button></section></div>`;}
function readingPage(){const n=readingMinutesFor(today()),pct=Math.min(100,Math.round(n/30*100));const items=[...state.readingEntries].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,24);return `${pageHeading('READING CORNER','阅读与听书','每天30分钟，纸本、电子书和听书可以自由组合。')}${banner()}<div class="reading-hero"><div><span class="micro-label">DAILY READING MOMENT</span><h2>每天留一点时间，<br>读一点喜欢的东西。</h2><p>不需要一次读完。10分钟 + 20分钟，也算完成一天。</p></div><div class="reading-hero-count">${n}<small>/ 30 分钟</small></div></div><div class="reading-page-grid"><section class="card"><div class="card-head"><div><div class="card-title">＋ 记录阅读或听书</div><div class="card-subtitle">可分多次添加，自动累计今日时长</div></div></div><form id="reading-form"><div class="field-row field-block"><div class="field"><label class="input-label">日期</label><input id="reading-date" class="input" type="date" value="${today()}" required></div><div class="field"><label class="input-label">形式</label><select class="input" id="reading-mode"><option value="read">看书</option><option value="listen">听书</option></select></div></div><div class="field-row field-block"><div class="field"><label class="input-label">分钟数</label><input id="reading-minutes" class="input" type="number" min="1" max="480" step="1" value="15" required></div><div class="field"><label class="input-label">书名 / 作品名称</label><input id="reading-title" class="input" maxlength="140" placeholder="例如：小王子"></div></div><div class="field-block"><label class="input-label">今天记住的一句话（选填）</label><input id="reading-note" class="input" maxlength="250" placeholder="一个让你印象深刻的观点"></div><button class="btn btn-primary" type="submit">保存阅读记录</button></form><div class="section-divider"></div><div class="card-head"><div><div class="card-title">今日累计</div><div class="card-subtitle">${n>=30?'已达到今天的30分钟目标':'距离目标还差 '+Math.max(0,30-n)+' 分钟'}</div></div><span class="pill pill-green">${pct}%</span></div><div class="progress-rail"><div class="progress-fill" style="width:${pct}%"></div></div><div class="btn-row"><button class="btn" data-action="reading-quick" data-minutes="10">＋ 10分钟看书</button><button class="btn" data-action="reading-quick" data-minutes="15">＋ 15分钟看书</button><button class="btn" data-action="reading-quick" data-minutes="30">＋ 30分钟看书</button></div></section><section class="card"><div class="card-head"><div><div class="card-title">近期阅读记录</div><div class="card-subtitle">本月累计 ${readingMinutesMonth()} 分钟，${readingDaysMonth()} 天达标</div></div></div>${items.length?`<div class="reading-log">${items.map(e=>`<div class="reading-log-item"><span class="reading-log-icon">${e.mode==='listen'?'◖':'▤'}</span><div class="reading-log-text"><strong>${safe(e.title||'自由阅读')}</strong><small>${safe(e.date)} · ${e.mode==='listen'?'听书':'看书'} · ${e.minutes} 分钟${e.note?' · '+safe(e.note):''}</small></div><button class="mini-delete" data-action="delete-reading" data-id="${safe(e.id)}">×</button></div>`).join('')}</div>`:'<div class="empty">还没有记录。今天从10分钟开始。</div>'}</section></div>`;}
let moneyAccountFilter='all',editingAccountId=null;
function accountCard(a){const isDebt=accountKind(a.type)==='debt',balance=balanceOf(a),kind=accountTypeText[a.type]||'账户';return `<div class="account-card ${isDebt?'is-debt':'is-asset'}"><div class="account-card-top"><span class="account-card-icon">${accountIcon[a.type]||'◉'}</span><span class="account-card-kind">${safe(kind)}</span></div><div class="account-card-name">${safe(a.name)}</div><div class="account-card-amount ${balance===null?'unset':''}">${balance===null?'待填写余额':money(balance)}</div>${a.minimumPayment&&isDebt?`<div class="account-meta">最低还款 ${money(a.minimumPayment)} ${a.dueDay?' · 每月 '+safe(a.dueDay)+' 日':''}</div>`:a.startDate&&balance!==null?`<div class="account-meta">起始日期 ${safe(a.startDate)}</div>`:'<div class="account-meta">请先核对当前金额</div>'}<button class="account-edit" data-action="edit-account" data-id="${safe(a.id)}">编辑 / 核对 ›</button></div>`;}
function accountEditor(){const a=accountById(editingAccountId),current=a?balanceOf(a):null;return `<section class="card account-editor" id="account-editor"><div class="card-head"><div><div class="card-title">${a?'编辑 / 核对账户':'＋ 新增账户'}</div><div class="card-subtitle">先输入真实起始余额，之后每笔交易会自动更新</div></div><button class="link-btn" data-action="cancel-account-edit">${a?'取消编辑':'收起'}</button></div><form id="account-form"><input type="hidden" id="account-id" value="${safe(a?.id||'')}"><div class="field-row field-block"><div class="field"><label class="input-label">账户名称</label><input class="input" id="account-name" required maxlength="60" placeholder="例如 CIMB" value="${safe(a?.name||'')}"></div><div class="field"><label class="input-label">账户种类</label><select id="account-type" class="input">${Object.entries(accountTypeText).map(([v,n])=>`<option value="${v}" ${a?.type===v?'selected':''}>${n}</option>`).join('')}</select></div></div><div class="field-row field-block"><div class="field"><label class="input-label">起始余额（RM）${a&&current!==null?' · 当前计算 '+money(current):''}</label><input class="input" type="number" id="account-opening" step="0.01" min="0" placeholder="留空表示尚未核对" value="${a&&hasBalance(a)?safe(a.openingBalance):''}"></div><div class="field"><label class="input-label">起始日期</label><input class="input" type="date" id="account-date" value="${safe(a?.startDate||today())}" required></div></div><div class="field-row field-block"><div class="field"><label class="input-label">最低还款额（欠款账户，可选）</label><input class="input" type="number" id="account-minimum" step="0.01" min="0" placeholder="例如 150.00" value="${a?.minimumPayment??''}"></div><div class="field"><label class="input-label">每月还款日（1至31号，可选）</label><input class="input" type="number" id="account-due" min="1" max="31" step="1" placeholder="例如 15" value="${a?.dueDay??''}"></div></div><div class="field-block"><label class="input-label">备注（选填）</label><input class="input" id="account-notes" maxlength="160" placeholder="银行、卡片或账单说明" value="${safe(a?.notes||'')}"></div><div class="btn-row"><button class="btn btn-primary" type="submit">保存账户</button>${a&&hasBalance(a)?`<button class="btn" type="button" data-action="reconcile-account" data-id="${safe(a.id)}">按最新账单对账</button>`:''}${a&&!ACCOUNT_TEMPLATES.some(x=>x[0]===a.id)?`<button class="btn btn-danger" type="button" data-action="delete-account" data-id="${safe(a.id)}">删除账户</button>`:''}</div><p class="section-note section-gap">起始余额应为开始记账前的金额。欠款账户填「尚欠金额」，不要填负数。更改起始余额会重新计算之后所有交易，请谨慎操作。</p></form></section>`;}
function financeSummary(){const known=knownAccounts(),missing=missingAccounts(),aTotal=assetTotal(),dTotal=debtTotal();return `<div class="finance-overview"><div class="finance-main-number"><span>我的总资产（已核对）</span><strong>${money(aTotal)}</strong><small>银行、现金及电子钱包余额</small></div><div class="finance-overview-side"><div><span>待偿还欠款（已核对）</span><strong>${money(dTotal)}</strong></div><div><span>净资产（仅已核对账户）</span><strong>${signed(aTotal-dTotal)}</strong></div></div></div>${missing.length?`<div class="banner warn"><span>还有 <strong>${missing.length}</strong> 个账户未填写余额，以上合计不完整。请先核对：${safe(missing.slice(0,3).map(x=>x.name).join('、'))}${missing.length>3?' 等':''}。</span><button class="btn btn-small" data-action="go-accounts">设置余额</button></div>`:''}`;}
function moneyPageV2(){const ta=allAccounts().filter(a=>accountKind(a.type)==='asset'),da=allAccounts().filter(a=>accountKind(a.type)==='debt');const list=[...state.transactions].filter(t=>moneyAccountFilter==='all'||[t.accountId,t.fromAccountId,t.toAccountId].includes(moneyAccountFilter)).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,100);const net=thisMonthIncome()-thisMonthExpenses();return `${pageHeading('MY FINANCIAL SPACE','我的财务管理','每个账户、每笔交易、每项欠款，都整理在同一个地方。',`<button class="btn" data-action="export-csv">↓ 导出交易</button>`)}${banner()}${financeSummary()}
<div class="finance-section-head" id="account-section"><div><h2>我的全部账户</h2><p>金额只按你输入的余额及交易计算，不连接银行实时数据。</p></div><button class="btn btn-primary btn-small" data-action="new-account">＋ 新增账户</button></div>
<div class="account-group-title">▣ 资产账户 <span>${ta.length} 个</span></div><div class="account-grid">${ta.map(accountCard).join('')}</div>
<div class="account-group-title debt-title">▤ 信用卡与分期欠款 <span>${da.length} 个</span></div><div class="account-grid debt-grid">${da.map(accountCard).join('')}</div>
${editingAccountId!==null?accountEditor():''}
<div class="finance-section-head"><div><h2>记一笔交易</h2><p>收支、账户转账和信用卡还款都支持，自动更新余额。</p></div></div>
<div class="finance-entry-grid"><section class="card"><form id="tx-form"><div class="field-row field-block"><div class="field"><label class="input-label">日期</label><input type="date" class="input" id="tx-date" value="${today()}" required></div><div class="field"><label class="input-label">交易类型</label><select id="tx-type" class="input"><option value="expense">日常支出 / 信用卡消费</option><option value="income">收入</option><option value="transfer">账户转账 / 信用卡还款</option></select></div></div><div class="field-row field-block"><div class="field"><label class="input-label">金额（RM）</label><input id="tx-amount" class="input" type="number" min="0.01" step="0.01" required placeholder="例如 12.50"></div><div class="field"><label class="input-label">分类</label><select id="tx-category" class="input"><option>餐饮</option><option>交通</option><option>房贷/租金</option><option>日用品</option><option>订阅</option><option>课程</option><option>娱乐</option><option>工资</option><option>副业</option><option>保险</option><option>医疗</option><option>其他</option></select></div></div><div class="field-block"><label class="input-label" id="tx-account-label">支出账户 / 使用哪张卡</label><select id="tx-account" class="input">${accountOptions('all','','请选择付款账户')}</select></div><div class="field-block" id="transfer-from-wrap" hidden><label class="input-label">从哪个资产账户转出</label><select id="tx-from" class="input">${accountOptions('asset','','请选择转出账户')}</select></div><div class="field-block" id="transfer-to-wrap" hidden><label class="input-label">转入账户 / 要还的信用卡</label><select id="tx-to" class="input">${accountOptions('all','','请选择收款账户')}</select></div><div class="field-block"><label class="input-label">备注（选填）</label><input class="input" id="tx-note" maxlength="150" placeholder="例如：午餐、AMEX还款"></div><button class="btn btn-primary" type="submit">＋ 保存交易</button><p class="section-note section-gap">从 Maybank 还 AMEX：选择「账户转账 / 信用卡还款」，不会重复算入支出。信用卡新消费选择「日常支出」并选对应信用卡。</p></form></section>
<section class="card finance-summary-card"><div class="card-head"><div><div class="card-title">本月收支概览</div><div class="card-subtitle">按消费发生日期统计，转账不算消费</div></div></div><div class="finance-figure"><span>本月收入</span><strong>${money(thisMonthIncome())}</strong></div><div class="finance-figure"><span>本月支出（含刷卡消费）</span><strong>${money(thisMonthExpenses())}</strong></div><div class="finance-figure strong"><span>本月收支差额</span><strong>${signed(net)}</strong></div><div class="section-divider"></div><div class="reading-corner-graphic finance-note-illustration">◈<span>记录清楚，选择更自由。</span></div></section></div>
<div class="finance-section-head"><div><h2>交易流水</h2><p>可按账户筛选，删除错误记录后余额会重新计算。</p></div><select class="input account-filter" id="money-account-filter"><option value="all">全部账户</option>${allAccounts().map(a=>`<option value="${safe(a.id)}" ${moneyAccountFilter===a.id?'selected':''}>${safe(a.name)}</option>`).join('')}</select></div>
<section class="card transaction-ledger">${financeTransactionsHTML(list)}${list.length>=100?'<p class="section-note">只显示最近100笔。所有交易均保留，可导出完整CSV。</p>':''}</section><div class="finance-bottom-note">重要说明：此应用不会连接银行或自动抓取账单。余额仅根据你手动输入的数据计算，信用卡利息与手续费也需要自行记录。请定期与真实银行账单核对。</div>`;}

function todayPage(){const hs=habitsForToday();const monthTasks=monthlyItems();return `${pageHeading('PERSONAL DASHBOARD',`今天，${dateName(today())}`, '少做一点，持续做下去。',`<button class="btn ${isBusy()?'btn-mint':''}" data-action="toggle-busy">${isBusy()?'✓ 忙碌日模式':'☼ 切换忙碌日'}</button>`)}${banner()}
<div class="stats-grid"><div class="stat-card"><div class="stat-label">今日习惯<span class="stat-icon">✓</span></div><div class="stat-number">${doneHabits()} <em>/ ${hs.length}</em></div><div class="stat-sub">坚持比完美重要</div></div><div class="stat-card"><div class="stat-label">本周学习<span class="stat-icon">▦</span></div><div class="stat-number">${studyDatesThisWeek()} <em>/ ${state.profile.weeklyTarget} 次</em></div><div class="stat-sub">每次至少15分钟</div></div><div class="stat-card"><div class="stat-label">本月支出<span class="stat-icon">◉</span></div><div class="stat-number" style="font-size:21px">${money(thisMonthExpenses())}</div><div class="stat-sub">需要管理，不是限制一切</div></div><div class="stat-card"><div class="stat-label">本月任务<span class="stat-icon">◎</span></div><div class="stat-number">${monthTasks.filter(t=>t.done).length} <em>/ ${monthTasks.length}</em></div><div class="stat-sub">每个月完成几件要紧事</div></div></div>
<div class="cols-2"><div class="stack"><section class="card"><div class="card-head"><div><div class="card-title">今日习惯清单</div><div class="card-subtitle">${isBusy()?'忙碌日只保留3项基本习惯':'勾选即保存，可随时修改'}</div></div><span class="pill pill-green">${isBusy()?'忙碌模式':'日常模式'}</span></div>${dailyHabitsHTML()}<div class="btn-row"><button class="btn btn-small" data-page="plan">管理习惯</button><button class="btn btn-small" data-page="review">月度回顾</button></div></section>
<section class="card"><div class="card-head"><div><div class="card-title">${monthName()} · 本月任务</div><div class="card-subtitle">${safe(state.monthlyFocus[month()]||'本月先做好一件事')}</div></div><button class="link-btn" data-page="plan">查看全部</button></div>${tasksHTML(true)}</section></div>
<div class="stack"><section class="card"><div class="card-head"><div><div class="card-title">专业技能学习</div><div class="card-subtitle">一周三次，持续累积</div></div><span class="pill">${studyThisMonth()} 分钟 / 月</span></div><div class="study-hero"><small>当前90天学习方向</small><strong>${safe(state.profile.skill)}</strong><span class="chip">每周目标：${state.profile.weeklyTarget}次</span></div><div class="progress-rail"><div class="progress-fill" style="width:${Math.min(100,studyDatesThisWeek()/Math.max(1,state.profile.weeklyTarget)*100)}%"></div></div><div class="progress-text"><span>本周完成 ${studyDatesThisWeek()} 次</span><span>目标 ${state.profile.weeklyTarget} 次</span></div><div class="btn-row"><button class="btn btn-primary btn-small" data-action="study-25">＋ 25分钟</button><button class="btn btn-small" data-action="study-5">＋ 5分钟</button><button class="btn btn-ghost btn-small" data-action="study-undo">撤销5分钟</button></div>${weeklyDots()}</section>
<section class="card"><div class="card-head"><div><div class="card-title">你的90天主目标</div><div class="card-subtitle">不同时开启太多新计划</div></div><button class="link-btn" data-page="plan">修改目标</button></div><div class="focus-box"><div class="focus-main">${safe(state.profile.focus)}</div><p class="section-note">目前只选择最重要的核心方向。其他想法先记录，不急着启动。</p></div></section>
<section class="card"><div class="card-head"><div><div class="card-title">今日收支记录</div><div class="card-subtitle">简单记录就很好</div></div><button class="link-btn" data-page="money">新增记录</button></div>${financeTransactionsHTML(todaysTransactions())}</section></div></div>`;}
function planPage(){return `${pageHeading('FOCUS & PLAN','目标计划','90天只专注一个主要方向，每个月完成少量真实任务。')}${banner()}<div class="goal-band"><div><small>未来90天最重要的事</small><h2>${safe(state.profile.focus)}</h2><p>先决定什么最重要，再决定今天做什么。</p></div><span class="pill pill-green">持续优先</span></div>
<div class="cols-2"><div class="stack"><section class="card"><div class="card-head"><div><div class="card-title">本月核心目标</div><div class="card-subtitle">${monthName()} · 每个月聚焦一件事</div></div></div><form id="monthly-focus-form" class="form-row"><input class="input" id="monthly-focus" required maxlength="160" value="${safe(state.monthlyFocus[month()]||'')}" placeholder="例如：建立稳定的财务记录"><button class="btn btn-primary">保存</button></form><div class="section-divider"></div><div class="card-head"><div><div class="card-title">本月可执行任务</div><div class="card-subtitle">每项应该能明确判断是否完成</div></div><span class="pill">${monthlyItems().filter(t=>t.done).length}/${monthlyItems().length}</span></div>${tasksHTML()}<form id="task-form" class="form-row section-gap"><input class="input" id="task-title" required maxlength="140" placeholder="新增任务，例如：核对信用卡余额"><button class="btn btn-primary">＋ 添加</button></form></section>
<section class="card"><div class="card-head"><div><div class="card-title">90天与每周学习计划</div><div class="card-subtitle">职业技能只保留一条主线</div></div></div><form id="profile-form"><div class="field-block"><label class="input-label" for="profile-focus">90天主目标</label><input class="input" id="profile-focus" required maxlength="160" value="${safe(state.profile.focus)}"></div><div class="field-block"><label class="input-label" for="profile-skill">当前学习方向</label><input class="input" id="profile-skill" required maxlength="160" value="${safe(state.profile.skill)}"></div><div class="field-block"><label class="input-label" for="weekly-target">每周学习次数（每次至少15分钟）</label><select class="input" id="weekly-target">${[1,2,3,4,5,6,7].map(n=>`<option value="${n}" ${n===Number(state.profile.weeklyTarget)?'selected':''}>每周 ${n} 次</option>`).join('')}</select></div><button class="btn btn-primary">保存计划</button></form></section></div>
<div class="stack"><section class="card"><div class="card-head"><div><div class="card-title">习惯管理</div><div class="card-subtitle">建议保持少量核心习惯，阅读为固定主习惯</div></div></div><div class="list-clean">${state.habits.map(h=>`<div class="task-row"><span class="pill">${safe(h.category)}</span><span class="task-text">${safe(h.name)}</span>${h.id==='reading'?'<span class="pill pill-green">固定</span>':`<button class="mini-delete" data-action="delete-habit" data-id="${safe(h.id)}" aria-label="删除习惯">×</button>`}</div>`).join('')}</div><form id="habit-form" class="section-gap"><div class="field-block"><input class="input" required id="habit-name" maxlength="70" placeholder="新习惯，例如：阅读10分钟"></div><div class="field-block"><input class="input" id="habit-hint" maxlength="120" placeholder="补充说明（选填）"></div><div class="form-row"><select class="input" id="habit-category"><option>生活</option><option>健康</option><option>学习</option><option>财务</option></select><button class="btn btn-primary">添加习惯</button></div></form><div class="section-divider"></div><p class="section-note">活动日保留安静时间、阅读、支出记录和复盘四项。删除后可在日常模式自由使用其他习惯。</p></section>
<section class="card"><div class="card-head"><div><div class="card-title">这90天的执行规则</div><div class="card-subtitle">简单、可重复、不会增加压力</div></div></div><div class="timeline"><div class="timeline-item"><div class="timeline-number">01</div><div><strong>只选一个职业学习主题</strong><p>其他课程先收藏，不立即开始。</p></div></div><div class="timeline-item"><div class="timeline-number">02</div><div><strong>每周累积3次短时间学习</strong><p>不追求一次学2小时，持续更重要。</p></div></div><div class="timeline-item"><div class="timeline-number">03</div><div><strong>每月产出一项实际成果</strong><p>课程笔记、系统功能或作品案例都可以。</p></div></div><div class="timeline-item"><div class="timeline-number">04</div><div><strong>错过一天不重新规划人生</strong><p>明天继续，不从零开始。</p></div></div></div></section></div></div>`;}
function moneyPage(){const net=thisMonthIncome()-thisMonthExpenses();return `${pageHeading('MONEY TRACKING','支出记录','先知道钱去了哪里，再决定怎么改善。',`<button data-action="export-csv" class="btn">↓ 导出收支表</button>`)}${banner()}<div class="summary-grid"><div class="summary-tile"><p>本月支出</p><strong>${money(thisMonthExpenses())}</strong><small>根据你手动记录的交易</small></div><div class="summary-tile"><p>本月收入</p><strong>${money(thisMonthIncome())}</strong><small>仅计算已输入金额</small></div><div class="summary-tile"><p>本月记录收支差额</p><strong style="color:${net<0?'#b05b54':'#208d70'}">${net<0?'−':''}${money(Math.abs(net))}</strong><small>不是银行真实余额</small></div></div><div class="cols-2"><section class="card"><div class="card-head"><div><div class="card-title">新增交易</div><div class="card-subtitle">每笔只填几个项目，容易坚持</div></div></div><form id="tx-form"><div class="field-row field-block"><div class="field"><label class="input-label" for="tx-date">日期</label><input class="input" type="date" id="tx-date" required value="${today()}"></div><div class="field"><label class="input-label" for="tx-type">类型</label><select class="input" id="tx-type"><option value="expense">支出</option><option value="income">收入</option></select></div></div><div class="field-row field-block"><div class="field"><label class="input-label" for="tx-amount">金额（RM）</label><input class="input" type="number" min="0.01" step="0.01" required id="tx-amount" placeholder="例如 12.50"></div><div class="field"><label class="input-label" for="tx-category">分类</label><select class="input" id="tx-category"><option>餐饮</option><option>交通</option><option>日用品</option><option>订阅</option><option>课程</option><option>娱乐</option><option>工资</option><option>副业</option><option>其他</option></select></div></div><div class="field-block"><label class="input-label" for="tx-note">备注（选填）</label><input class="input" id="tx-note" maxlength="140" placeholder="例如：午餐、油费"></div><button class="btn btn-primary">＋ 保存记录</button></form><div class="section-divider"></div><div class="notice-line">这里只记录你输入的收支，不会自动连接银行，也不会推断你的真实账户余额。重要付款与账单请同时核对银行记录。</div></section><section class="card"><div class="card-head"><div><div class="card-title">最近交易</div><div class="card-subtitle">按日期显示最近20笔</div></div><span class="pill">${state.transactions.length} 笔</span></div>${recentTransactionsHTML([...state.transactions].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,20))}</section></div>`;}
function reviewPage(){const r=state.reviews[month()]||{};const qs=[['wins','这个月最值得肯定的一件事'],['friction','时间主要消耗在哪里'],['result','本月真正完成的成果'],['next','下个月只重点改善什么']];const doneTasks=monthlyItems().filter(t=>t.done).length;return `${pageHeading('MONTHLY REVIEW','月度回顾','不评判自己，只用事实了解进度。')}${banner()}<div class="stats-grid"><div class="stat-card"><div class="stat-label">本月学习总时长<span class="stat-icon">▤</span></div><div class="stat-number">${studyThisMonth()} <em>分钟</em></div><div class="stat-sub">累积胜过突击</div></div><div class="stat-card"><div class="stat-label">已完成任务<span class="stat-icon">✓</span></div><div class="stat-number">${doneTasks} <em>项</em></div><div class="stat-sub">总共 ${monthlyItems().length} 项</div></div><div class="stat-card"><div class="stat-label">本月有打卡的天数<span class="stat-icon">▦</span></div><div class="stat-number">${Object.entries(state.checks).filter(([d,items])=>d.startsWith(month())&&Object.values(items).some(Boolean)).length} <em>天</em></div><div class="stat-sub">中断了也可以继续</div></div><div class="stat-card"><div class="stat-label">收支记录<span class="stat-icon">◉</span></div><div class="stat-number">${state.transactions.filter(t=>t.date.startsWith(month())).length} <em>笔</em></div><div class="stat-sub">真实记录比估计准确</div></div></div><div class="cols-2"><section class="card"><div class="card-head"><div><div class="card-title">${monthName()} · 我的复盘</div><div class="card-subtitle">每个月填一次就足够</div></div></div><form id="review-form" class="review-questions">${qs.map(([key,label],i)=>`<div><label class="input-label" for="review-${key}">${i+1}. ${label}</label><textarea class="input" id="review-${key}" rows="4" maxlength="1200" placeholder="用1至3句话简单回答">${safe(r[key]||'')}</textarea></div>`).join('')}<button class="btn btn-primary">保存本月回顾</button></form></section><section class="card"><div class="card-head"><div><div class="card-title">本月目标回顾</div><div class="card-subtitle">记录客观结果，而不是只看心情</div></div></div><div class="focus-box"><div class="text-xs muted">本月最重要的目标</div><div class="focus-main">${safe(state.monthlyFocus[month()]||'尚未设定')}</div></div><div class="section-gap">${tasksHTML()}</div><div class="section-divider"></div><p class="section-note">如果本月只完成了一项重要任务，也是真实成果。不要因为打卡不是100%就否定整个月。</p></section></div>`;}
function settingsPage(){const account=session?.user?.email;return `${pageHeading('SETTINGS & CLOUD','设置与同步','本机可直接试用；登录后数据才能跨手机与电脑同步。')}${banner()}<div class="cols-2"><div class="stack"><section class="card"><div class="card-head"><div><div class="card-title">云端同步</div><div class="card-subtitle">保护个人数据，需要单独的 Supabase 账户</div></div><span class="pill ${account?'pill-green':''}">${account?'已登录':'本机模式'}</span></div>${!cloudConfigured?`<div class="alert">尚未配置云端数据库。所有数据目前保存在这台设备的浏览器中，换手机或换电脑不会自动同步。</div><div class="section-divider"></div><div class="timeline"><div class="timeline-item"><span class="timeline-number">1</span><div><strong>建立 Supabase 免费项目</strong><p>在 Supabase 创建项目，打开 SQL Editor。</p></div></div><div class="timeline-item"><span class="timeline-number">2</span><div><strong>运行项目附带的 SQL</strong><p>复制 supabase-setup.sql 执行，开启用户数据隔离。</p></div></div><div class="timeline-item"><span class="timeline-number">3</span><div><strong>修改 config.js</strong><p>填写 Project URL 和 Publishable Key，重新上传至 GitHub。</p></div></div><div class="timeline-item"><span class="timeline-number">4</span><div><strong>回来注册、登录</strong><p>在手机和电脑使用同一个账号，数据即可同步。</p></div></div></div>`:account?`<div class="alert success">已登录：<strong>${safe(account)}</strong><br>每次修改自动保存到本机，并尝试同步到你的云端记录。</div>${syncIssue==='conflict'?`<div class="alert error section-gap"><strong>不同设备数据发生冲突。</strong><br>请先决定使用哪一份数据，不会自动覆盖。建议先导出本机备份。</div><div class="btn-row"><button class="btn" data-action="load-cloud">保留云端版本</button><button class="btn btn-danger" data-action="force-upload">覆盖云端版本</button></div>`:''}<div class="btn-row"><button class="btn btn-primary" data-action="retry-sync">立即同步</button><button class="btn" data-action="signout">退出登录</button></div>`:`<form id="login-form" class="cloud-form"><div><label class="input-label" for="login-email">电子邮箱</label><input class="input" type="email" autocomplete="email" id="login-email" required placeholder="you@example.com"></div><div><label class="input-label" for="login-password">密码（至少6位）</label><input class="input" type="password" autocomplete="current-password" minlength="6" id="login-password" required placeholder="输入密码"></div><div class="btn-row"><button class="btn btn-primary" type="submit">登录云端</button><button class="btn" type="button" data-action="signup">新用户注册</button></div></form><p class="section-note section-gap">首次注册可能需要前往邮箱确认。完成确认后再登录。若你已在本机填写数据，首次连接空白云端账户时会上传本机记录。</p>`}</section>
<section class="card"><div class="card-head"><div><div class="card-title">备份与导入</div><div class="card-subtitle">建议每月导出一次自己的记录</div></div></div><div class="btn-row"><button class="btn btn-primary" data-action="export-json">↓ 导出全部数据</button><button class="btn" data-action="import-click">↑ 导入备份</button></div><input id="import-file" style="display:none" type="file" accept="application/json,.json"><div class="section-divider"></div><p class="section-note">导入会替换应用当前数据。云端登录状态下，导入也会同步覆盖你账号的现有记录，请先备份。</p></section></div>
<div class="stack"><section class="card"><div class="card-head"><div><div class="card-title">你的数据安全吗？</div><div class="card-subtitle">使用前需要了解</div></div></div><div class="setting-line"><div><strong>GitHub Pages</strong><span>负责显示应用页面，不是私人数据库</span></div><span class="pill">网页托管</span></div><div class="setting-line"><div><strong>Supabase</strong><span>登录后保存个人记录，按用户隔离访问</span></div><span class="pill">云端数据</span></div><div class="setting-line"><div><strong>本机存储</strong><span>不登录也能用，但换设备不会同步</span></div><span class="pill">离线记录</span></div><div class="section-divider"></div><div class="notice-line">不要把 Secret Key、service_role 密钥或银行密码放进 config.js。此应用只是个人管理工具，没有连接任何银行账户。多台设备同时离线修改同一份数据时，需要手动处理同步冲突。</div></section>
<section class="card"><div class="card-head"><div><div class="card-title">建议使用方式</div><div class="card-subtitle">别把工具也变成新的压力</div></div></div><div class="timeline"><div class="timeline-item"><span class="timeline-number">早</span><div><strong>早上2分钟</strong><p>打开今天，确认当天最重要的事情。</p></div></div><div class="timeline-item"><span class="timeline-number">晚</span><div><strong>晚上3分钟</strong><p>完成勾选、补录收支。</p></div></div><div class="timeline-item"><span class="timeline-number">周</span><div><strong>每周日15分钟</strong><p>看看财务、学习和下一周安排。</p></div></div><div class="timeline-item"><span class="timeline-number">月</span><div><strong>每月最后一天15分钟</strong><p>填写一次月度回顾，决定下月重点。</p></div></div></div></section></div></div>`;}
function updateTransactionForm(){const t=$('#tx-type')?.value;if(!t)return;const transfer=t==='transfer';const account=$('#tx-account')?.closest('.field-block');if(account)account.hidden=transfer;for(const id of ['#transfer-from-wrap','#transfer-to-wrap']){const e=$(id);if(e)e.hidden=!transfer;}const label=$('#tx-account-label');if(label)label.textContent=t==='income'?'收入存入哪个资产账户':'支出账户 / 使用哪张卡';if(!transfer&&t==='income'){const sel=$('#tx-account');if(sel){const value=sel.value;sel.innerHTML=accountOptions('asset',value,'请选择收入账户');}}else if(!transfer&&t==='expense'){const sel=$('#tx-account');if(sel){const value=sel.value;sel.innerHTML=accountOptions('all',value,'请选择付款账户');}}}
function render(){showPageTitle();const views={today:updatedTodayPage,plan:planPage,reading:readingPage,money:moneyPageV2,review:reviewPage,settings:settingsPage};$('#main-content').innerHTML=views[page]();if(page==='money')updateTransactionForm();$('#footer-date').textContent=monthName();updateStatus();}
function getId(action,button){return button.dataset.id||'';}
function confirmDelete(label){return confirm(`确定删除「${label}」吗？此操作不可撤销。`);}
function saveBlob(filename,content,type){const a=document.createElement('a'),blob=new Blob([content],{type});const url=URL.createObjectURL(blob);a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportData(){saveBlob(`Focus-全部记录-${today()}.json`,JSON.stringify(state,null,2),'application/json;charset=utf-8');notice('已生成数据备份');}
function exportCSV(){const rows=[['日期','类型','转出/交易账户','转入账户','分类','金额 RM','对账差额 RM','备注'],...state.transactions.map(t=>[t.date,transactionLabel(t),t.type==='transfer'?accountLabel(t.fromAccountId):accountLabel(t.accountId),t.type==='transfer'?accountLabel(t.toAccountId):'',t.category||'',t.amount,t.type==='adjustment'?t.delta:'',t.note||''])];saveBlob(`Focus-收支记录-${today()}.csv`,'\ufeff'+rows.map(row=>row.map(x=>'"'+String(x).replace(/"/g,'""')+'"').join(',')).join('\r\n'),'text/csv;charset=utf-8');notice('已导出收支 CSV');}
function dispatch(action,btn){const id=getId(action,btn);switch(action){
case 'go-reading':route('reading');break;
case 'toggle-habit':{if(id==='reading'){route('reading');break;}state.checks[today()]??={};state.checks[today()][id]=!state.checks[today()][id];commit();break;}
case 'toggle-busy':state.busyDays[today()]=!isBusy();commit(isBusy()?'已切换为忙碌日，只做基本习惯':'已恢复日常模式');break;
case 'study-25':case 'study-5':{state.studyEntries[today()]=asNumber(state.studyEntries[today()])+(action==='study-25'?25:5);commit('已记录学习时间');break;}
case 'study-undo':state.studyEntries[today()]=Math.max(0,asNumber(state.studyEntries[today()])-5);commit();break;
case 'toggle-task':{const t=monthlyItems().find(t=>t.id===id);if(t){t.done=!t.done;commit();}break;}
case 'delete-task':{const t=monthlyItems().find(t=>t.id===id);if(t&&confirmDelete(t.title)){state.monthlyTasks[month()]=monthlyItems().filter(x=>x.id!==id);commit();}break;}
case 'delete-habit':{const h=state.habits.find(h=>h.id===id);if(h&&confirmDelete(h.name)){state.habits=state.habits.filter(x=>x.id!==id);commit();}break;}
case 'delete-reading':{const e=state.readingEntries.find(x=>x.id===id);if(e&&confirmDelete(e.title||String(e.minutes)+'分钟阅读')){state.readingEntries=state.readingEntries.filter(x=>x.id!==id);commit();}break;}
case 'reading-quick':{const minutes=Number(btn.dataset.minutes);state.readingEntries.push({id:uid(),date:today(),minutes,mode:'read',title:'',note:''});commit('已记录 '+minutes+' 分钟');break;}
case 'new-account':editingAccountId='';render();setTimeout(()=>$('#account-editor')?.scrollIntoView({behavior:'smooth',block:'center'}),60);break;
case 'cancel-account-edit':editingAccountId=null;render();break;
case 'edit-account':editingAccountId=id;render();setTimeout(()=>$('#account-editor')?.scrollIntoView({behavior:'smooth',block:'center'}),60);break;
case 'go-accounts':$('#account-section')?.scrollIntoView({behavior:'smooth'});break;
case 'reconcile-account':{const a=accountById(id),current=balanceOf(a);if(current===null){notice('请先填写起始余额');break;}const entered=prompt(`请输入「${a.name}」今天实际的${accountKind(a.type)==='debt'?'尚欠金额':'账户余额'}（RM）。\n当前系统计算：${money(current)}`);if(entered===null)break;const val=Number(entered.trim());if(entered.trim()===''||!Number.isFinite(val)||val<0){notice('请输入不小于0的有效金额');break;}const delta=Math.round((val-current)*100)/100;if(delta===0){notice('余额已经一致，无需调整');break;}state.transactions.push({id:uid(),date:today(),type:'adjustment',amount:Math.abs(delta),delta,accountId:a.id,category:'对账',note:'手动对账调整'});commit('已更新对账差额：'+signed(delta));break;}
case 'delete-account':{const a=accountById(id);if(!a||ACCOUNT_TEMPLATES.some(x=>x[0]===id))break;if(state.transactions.some(t=>[t.accountId,t.fromAccountId,t.toAccountId].includes(id))){notice('账户有交易记录，请先删除对应记录');break;}if(confirmDelete(a.name)){state.accounts=state.accounts.filter(x=>x.id!==id);editingAccountId=null;commit();}break;}
case 'edit-tx':{const t=state.transactions.find(x=>x.id===id);if(!t)break;if(t.type==='adjustment'){notice('对账记录请删除后重新对账');break;}const entered=prompt(`修改「${t.note||transactionLabel(t)}」的金额（RM）`,String(t.amount));if(entered===null)break;const val=Number(entered.trim());if(entered.trim()===''||!Number.isFinite(val)||val<=0){notice('请输入有效金额');break;}const newDate=prompt('修改日期（YYYY-MM-DD）',t.date);if(newDate===null)break;if(!isValidDate(newDate)){notice('日期格式不正确');break;}const ids=t.type==='transfer'?[t.fromAccountId,t.toAccountId]:[t.accountId];if(ids.some(aid=>accountById(aid)&&newDate<accountById(aid).startDate)){notice('日期不能早于账户起始日期');break;}const newNote=prompt('修改备注',t.note||'');if(newNote===null)break;t.date=newDate;t.amount=Math.round(val*100)/100;t.note=newNote.slice(0,150);commit('已修改交易金额、日期和备注');break;}
case 'delete-tx':{const t=state.transactions.find(t=>t.id===id);if(t&&confirmDelete(t.note||money(t.amount))){state.transactions=state.transactions.filter(x=>x.id!==id);commit();}break;}
case 'export-csv':exportCSV();break;case 'export-json':exportData();break;case 'import-click':$('#import-file')?.click();break;
case 'signup':signUp();break;case 'signout':signOut();break;case 'retry-sync':if(session)syncNow();else notice('请先登录');break;
case 'load-cloud':pullCloud(true);break;case 'force-upload':if(confirm('这会用本机记录覆盖云端记录。确定要继续吗？'))syncNow(true);break;
}}
document.addEventListener('click',e=>{const p=e.target.closest('[data-page]');if(p){route(p.dataset.page);return;}const b=e.target.closest('[data-action]');if(b)dispatch(b.dataset.action,b);});
document.addEventListener('submit',e=>{const id=e.target.id;if(!['monthly-focus-form','task-form','habit-form','profile-form','tx-form','review-form','login-form','reading-form','account-form'].includes(id))return;e.preventDefault();switch(id){
case 'monthly-focus-form':{const value=$('#monthly-focus').value.trim();if(!value)return;state.monthlyFocus[month()]=value;commit('本月目标已更新');break;}
case 'task-form':{const value=$('#task-title').value.trim();if(!value)return;(state.monthlyTasks[month()]??=[]).push({id:uid(),title:value,done:false});commit('已添加任务');break;}
case 'habit-form':{const name=$('#habit-name').value.trim(),hint=$('#habit-hint').value.trim(),category=$('#habit-category').value;if(!name)return;if(state.habits.length>=15){notice('最多允许15个习惯，建议保持3至5个');return;}state.habits.push({id:uid(),name,hint,category});commit('已添加习惯');break;}
case 'profile-form':{state.profile.focus=$('#profile-focus').value.trim();state.profile.skill=$('#profile-skill').value.trim();state.profile.weeklyTarget=Number($('#weekly-target').value)||3;commit('90天计划已更新');break;}
case 'reading-form':{const date=$('#reading-date').value,minutes=Number($('#reading-minutes').value);if(!isValidDate(date)||!Number.isInteger(minutes)||minutes<1||minutes>480){notice('请输入正确日期和1至480分钟');return;}state.readingEntries.push({id:uid(),date,minutes,mode:$('#reading-mode').value,title:$('#reading-title').value.trim(),note:$('#reading-note').value.trim()});commit('已记录阅读 / 听书');break;}
case 'account-form':{const id=$('#account-id').value||uid(),type=$('#account-type').value,name=$('#account-name').value.trim(),openingText=$('#account-opening').value.trim(),startDate=$('#account-date').value;const openingBalance=openingText===''?null:Number(openingText);const minimumText=$('#account-minimum').value.trim(),dueText=$('#account-due').value.trim();const min=minimumText===''?null:Number(minimumText),due=dueText===''?null:Number(dueText);if(!name||!accountTypeText[type]||!isValidDate(startDate)||openingBalance!==null&&(!Number.isFinite(openingBalance)||openingBalance<0)||min!==null&&(!Number.isFinite(min)||min<0)||due!==null&&(!Number.isInteger(due)||due<1||due>31)){notice('请检查账户名称、日期、余额和还款日');return;}const old=accountById(id);if(old&&state.transactions.some(t=>[t.accountId,t.fromAccountId,t.toAccountId].includes(id))&&(old.type!==type||old.startDate!==startDate)&&!confirm('修改账户种类或起始日期会影响既有交易的计算，确定继续吗？'))return;const data={id,name,type,openingBalance,startDate,minimumPayment:min,dueDay:due,notes:$('#account-notes').value.trim()};if(old)Object.assign(old,data);else state.accounts.push(data);editingAccountId=null;commit('已保存账户信息');break;}
case 'tx-form':{const type=$('#tx-type').value,amount=Number($('#tx-amount').value),date=$('#tx-date').value;if(!['income','expense','transfer'].includes(type)||!Number.isFinite(amount)||amount<=0||!isValidDate(date)){notice('请输入正确交易日期与金额');return;}const tx={id:uid(),date,type,amount:Math.round(amount*100)/100,category:$('#tx-category').value,note:$('#tx-note').value.trim()};let targetAccounts=[];if(type==='transfer'){tx.fromAccountId=$('#tx-from').value;tx.toAccountId=$('#tx-to').value;if(!tx.fromAccountId||!tx.toAccountId||tx.fromAccountId===tx.toAccountId||accountKind(accountById(tx.fromAccountId)?.type)!=='asset'){notice('请选择两个不同账户，转出账户必须为资产账户');return;}targetAccounts=[accountById(tx.fromAccountId),accountById(tx.toAccountId)];}else{tx.accountId=$('#tx-account').value;const account=accountById(tx.accountId);if(!account){notice('请选择交易对应的账户');return;}if(type==='income'&&accountKind(account.type)==='debt'){notice('收入请选择银行、钱包或现金账户');return;}targetAccounts=[account];}if(targetAccounts.some(a=>!a||!hasBalance(a))){notice('请先在「我的全部账户」设置涉及账户的起始余额');return;}if(targetAccounts.some(a=>date<a.startDate)){notice('交易日期不能早于账户起始余额日期。请检查起始日期或交易日期');return;}if(type==='transfer'&&balanceOf(targetAccounts[0])<amount&&!confirm('转出金额高于当前账户余额，仍要保存吗？'))return;state.transactions.push(tx);commit('交易已保存，关联账户余额已更新');break;}
case 'review-form':{const obj={};for(const k of ['wins','friction','result','next'])obj[k]=$('#review-'+k).value.trim();state.reviews[month()]=obj;commit('月度复盘已保存');break;}
case 'login-form':signIn();break;
}});
document.addEventListener('change',async e=>{if(e.target.id==='tx-type'){updateTransactionForm();return;}if(e.target.id==='money-account-filter'){moneyAccountFilter=e.target.value;render();return;}if(e.target.id!=='import-file')return;const f=e.target.files?.[0];if(!f)return;try{const parsed=JSON.parse(await f.text());if(!Array.isArray(parsed.habits)||!Array.isArray(parsed.transactions)||!parsed.profile)throw new Error('格式不正确');if(!confirm('导入将替换当前全部记录。确定继续吗？'))return;state=normalize(parsed);commit('数据导入完成');}catch(err){notice('导入失败：不是有效的 Focus 备份');}finally{e.target.value='';}});
// Cloud synchronization. GitHub Pages serves static files; Supabase holds private, per-user records.
const DIRTY_STORAGE='focus_app_dirty_v1';
dirty=!!read(DIRTY_STORAGE,false);
function setDirty(value){dirty=!!value;saveTo(DIRTY_STORAGE,dirty);}
function scheduleSync(){if(!session)return;clearTimeout(syncTimer);syncTimer=setTimeout(()=>syncNow(),700);updateStatus();}
async function jsonFetch(url,options={}){const res=await fetch(url,options);let data=null;try{data=await res.json();}catch{}if(!res.ok){const msg=data?.msg||data?.message||data?.error_description||data?.error||`${res.status} 网络错误`;const er=new Error(msg);er.status=res.status;throw er;}return data;}
async function authRequest(path,body){return jsonFetch(CLOUD_URL+'/auth/v1/'+path,{method:'POST',headers:{'Content-Type':'application/json','apikey':CLOUD_KEY},body:JSON.stringify(body)});}
function adoptSession(data){if(!data?.access_token||!data?.refresh_token||!data?.user?.id)throw new Error('未收到有效的登录信息');session={access_token:data.access_token,refresh_token:data.refresh_token,user:data.user,expires_at:Date.now()+Number(data.expires_in||3600)*1000};saveTo(SESSION_STORAGE,session);}
async function refreshSession(){if(!session?.refresh_token)throw new Error('登录已失效');const data=await authRequest('token?grant_type=refresh_token',{refresh_token:session.refresh_token});adoptSession(data);return session;}
async function apiRequest(path,options={},retry=true){if(!session)throw new Error('请先登录');if(session.expires_at<Date.now()+25000)await refreshSession();const headers={'apikey':CLOUD_KEY,'Authorization':'Bearer '+session.access_token,'Content-Type':'application/json',...options.headers};try{return await jsonFetch(CLOUD_URL+'/rest/v1/'+path,{...options,headers});}catch(err){if(retry&&err.status===401){await refreshSession();return apiRequest(path,options,false);}throw err;}}
async function getRemote(){const rows=await apiRequest(`focus_user_data?user_id=eq.${encodeURIComponent(session.user.id)}&select=payload,updated_at&limit=1`,{method:'GET'});return rows?.[0]||null;}
function storeMeta(stamp){meta={userId:session.user.id,stamp:stamp||null};saveTo(META_STORAGE,meta);}
async function pullCloud(force=false){if(!session||!cloudConfigured)return;try{const remote=await getRemote();if(!remote){setDirty(true);await syncNow(true);return;}if(dirty&&!force&&meta?.userId===session.user.id){if(meta.stamp!==remote.updated_at){syncIssue='conflict';render();return;}await syncNow();return;}if(dirty&&!force&&meta?.userId!==session.user.id){localStorage.setItem('focus_last_local_backup',JSON.stringify(state));}
state=normalize(remote.payload);saveTo(STORAGE,state);storeMeta(remote.updated_at);setDirty(false);syncIssue='';render();notice('已载入云端最新记录');}catch(err){syncIssue='network';render();notice('载入云端失败：'+err.message);}}
async function syncNow(force=false){if(!session||!cloudConfigured||syncing)return;if(syncIssue==='conflict'&&!force){render();return;}syncing=true;updateStatus();try{const remote=await getRemote();if(remote&&!force&&(!meta||meta.userId!==session.user.id||meta.stamp!==remote.updated_at)){syncIssue='conflict';render();return;}if(!dirty&&!force){syncIssue='';updateStatus();return;}const submitted=JSON.stringify(state);const rows=await apiRequest('focus_user_data?on_conflict=user_id',{method:'POST',headers:{'Prefer':'resolution=merge-duplicates,return=representation'},body:JSON.stringify({user_id:session.user.id,payload:JSON.parse(submitted)})});storeMeta(rows?.[0]?.updated_at||new Date().toISOString());if(JSON.stringify(state)===submitted)setDirty(false);syncIssue='';updateStatus();}catch(err){syncIssue='network';updateStatus();notice('未能同步，本机数据已保留：'+err.message);}finally{syncing=false;render();if(dirty&&!syncIssue)scheduleSync();}}
async function signIn(){if(!cloudConfigured)return;const email=$('#login-email')?.value.trim(),password=$('#login-password')?.value;if(!email||!password)return;const btn=$('#login-form button[type="submit"]');if(btn){btn.disabled=true;btn.textContent='登录中…';}try{const data=await authRequest('token?grant_type=password',{email,password});adoptSession(data);await pullCloud();notice('登录成功');}catch(err){notice('登录失败：'+err.message);if(btn){btn.disabled=false;btn.textContent='登录云端';}}}
async function signUp(){if(!cloudConfigured)return;const email=$('#login-email')?.value.trim(),password=$('#login-password')?.value;if(!email||!password){notice('请先填写电子邮箱和密码');return;}if(password.length<6){notice('密码至少需要6位');return;}try{const data=await authRequest('signup',{email,password});if(data?.access_token){adoptSession(data);await pullCloud();notice('注册并登录成功');}else notice('注册已提交，请到邮箱查收验证邮件，验证后再登录');}catch(err){notice('注册失败：'+err.message);}}
async function signOut(){if(!confirm('确定退出登录吗？本机记录将清除。尚未同步的修改可能丢失，请先确认云端已同步或导出备份。'))return;const old=session;session=null;localStorage.removeItem(SESSION_STORAGE);localStorage.removeItem(META_STORAGE);localStorage.removeItem(DIRTY_STORAGE);localStorage.removeItem(STORAGE);meta=null;setDirty(false);syncIssue='';state=seed();saveTo(STORAGE,state);render();notice('已退出登录。本机已恢复空白示例计划。');if(old?.access_token)fetch(CLOUD_URL+'/auth/v1/logout',{method:'POST',headers:{'apikey':CLOUD_KEY,'Authorization':'Bearer '+old.access_token}}).catch(()=>{});}
async function initialize(){render();if(!cloudConfigured||!session)return;try{if(!session.user?.id||!session.refresh_token)throw new Error('登录过期');if(session.expires_at<Date.now()+60000)await refreshSession();await pullCloud();}catch(err){syncIssue='network';render();notice('云端连接失败，本机记录仍可使用');}}
window.addEventListener('online',()=>{if(session){if(dirty)syncNow();else pullCloud(true);}});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&session&&!syncing&&!syncIssue){if(dirty)syncNow();else pullCloud(true);}});
$('#account-shortcut').addEventListener('click',()=>route('settings'));
if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(()=>{});
initialize();
